document.addEventListener('DOMContentLoaded', function(){
  // TV mode — triggered by hostname OR legacy ?tv=1 param
  var isTVSite = window.location.hostname === 'jrctv.hlsr.app' ||
                 window.location.search.indexOf('tv=1') >= 0;
  if(isTVSite){
    document.documentElement.classList.add('tv-mode');
    // Hide login, show app shell immediately
    var ls = document.getElementById('login-screen'); if(ls) ls.style.display='none';
    var ma = document.getElementById('main-app'); if(ma) ma.style.display='block';
    // Load state from Neon first — board renders after currentDate arrives
    loadState();
    startPolling();
    // Login as board after brief delay (Neon usually responds in ~500ms)
    var _tvDone = false;
    function _doTVLogin(){
      if(_tvDone) return; _tvDone = true;
      loginAs('board');
    }
    setTimeout(_doTVLogin, 600);
    setTimeout(_doTVLogin, 2500); // retry if Neon slow
    return;
  }

  var hlsrB64 = null; // loaded from /assets/hlsr-header.webp
  var loginHlsrB64 = null; // loaded from /assets/hlsr-logo-login.png
  var h = document.getElementById('hlsr-logo');
  if(h) h.src = '/assets/hlsr-header.webp';
  var ll = document.getElementById('login-logo');
  if(ll) ll.src = '/assets/hlsr-logo-login.png';
  // Partner mode — triggered by hostname OR legacy ?partner=1 param
  var isPartnerSite = window.location.hostname === 'jrcpartner.hlsr.app' ||
                      window.location.search.indexOf('partner=1') >= 0;

  if(!isPartnerSite && _restoreLogin()) return;
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeReqEdit(); });

  // Pre-load adults from Neon so login form works immediately
  _preloadAdults();

  if(isPartnerSite){
    // Enter partner mode immediately — no timeout needed, DOM is ready
    enterPartnerMode();
    return;
  }
});

// Large login logo
(function(){
  var lb64 = '';
  var ll = document.getElementById('login-logo');
  if(ll) ll.src = 'data:image/webp;base64,' + lb64;
})();

